import{_ as a,o as t,c as l,a5 as p}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"写作课作业-094","description":"","frontmatter":{"date":"2020-10-22T19:39:31","title":"写作课作业-094","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/092.md","filePath":"posts/homework/092.md"}'),h={name:"posts/homework/092.md"};function i(o,e,r,n,s,d){return t(),l("div",null,[...e[0]||(e[0]=[p('<blockquote><p>10.21写作作业：读一篇好文章（给链接），问以下三个问题，认真写下答案：</p><p>【作者想要向我传递什么样的感知？</p><p>【作者做得成功吗？】</p><p>【如果我是他，我会怎么做，怎么做更加有效？】</p></blockquote><p>今天读的文章是郝景芳的《孩子，愿你一生勇敢心中有光》之《自序》。</p><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>如果我们希望孩子始终保持对未来的期望和人生理想，那么最好的办法绝不是拿孩子去跟“别人家的孩子”进行比较，而是带他走入一片更广阔的宇宙空间，他则会知道，这个世界上的真正的智慧在哪里，世界的深邃和美在哪里，能感受打世界的大、智慧的高，才有无限自我提升的勇气。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>心中有了遥远的光，自己做得好的时候，不好觉得自己成功，出现气馁时也能继续鼓起勇气前进。</p><p>家庭教育的最高境界就是让孩子觉得：这一切都是我自己做到的。</p><p>父母最重要的助推就是带我阅读，父母的助推，还体现在并不限制我的兴趣，让我广泛接触，自我选择。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>作者通过我心中的自己和“别人家的孩子”的不同感受，引出遥远的光——“未来我的人生要像这样”。</p><p>不同的年龄阶段因为阅读有了不同的选择，因为遥远的光，追求做得更好，虽然反复失落和忧伤，但能继续鼓起勇气前进，有了意想不到的收获。现在回想起来，所有的忧伤都是值得的，忧伤因为有追求。</p><p>父母最重要的助推就是带我阅读，父母的助推，还体现在并不限制我的兴趣，让我广泛接触，自我选择。也因为广泛阅读各种类型的书籍，各个类型的书之间往往能产生奇妙的碰撞，这样就会形成跨学科思维。</p><p>对女儿的教育方式，像母亲那样给她读书。选择书的品质，但不限定书的类型。对女儿进行文学和科学的双重启蒙。</p><p>自己阅读的三个阶段：</p><ul><li>带我读书</li><li>让我寻找阅读的乐趣</li><li>大量我接触更好的书籍</li></ul><p>我的所有梦想与失落、忧伤与坚强，都源于阅读。阅读让我有骄傲的梦想，也让我有谦卑的自知，让我知道，自己没有做到的，永远比做到的多得多。</p><p>能感受世界的大、智慧的高，才有无限的自我提升的勇气。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><p>把梦做大一点没有坏处，梦做大了，现实中的挑战都是小事。</p><p>广泛阅读各种类型的书籍，各个类型的书之间往往能产生奇妙的碰撞，这样就会形成跨学科思维。</p><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>“我心中对高考的感觉就是这样。我知道自己需要通过高考，但从来没有把高考当作目标。高考只是我摘星之梦的一小步，距离洞悉宇宙的秘密还有十万八千里。”</p><p>人和人的差距就是这么大，在自己以为高考只是完成对父母的期待，有些人却想好了自己的未来，把自己的梦做得那么大。贫穷限制了我的想象力。</p><p>虽然梦没做得这么大，自己也因为读书而有所改变，而阅读就是一个不断开眼的过程。</p><p>带动小孩读书最好的方式，就是自己要多阅读。自己加入BOX定投践行群，参加写作课，就是想有更多的改变。</p><p>而今天重听了课程「拼命思考未来」，是不是和「把梦做大一点」一样的呢？</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',34)])])}const _=a(h,[["render",i]]);export{u as __pageData,_ as default};
